// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address sender) public {
        vm.assume(sender != c.owner());
        amount = bound(amount, 0, 100_000 ether);

        Reverter reverter = new Reverter();
        vm.deal(sender, amount);

        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, address(reverter), amount, ""));

        Acceptor acceptor = new Acceptor();

        vm.prank(sender);
        (bool ok2, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.sendMoney.selector, address(acceptor), amount, ""));

        assertTrue(ok2 == false, "Non-owner should not be able to successfully call sendMoney");
    }
}

contract Acceptor {
    fallback() external payable { }
}

contract Reverter {
    fallback() external payable { revert(); }
}
